{
  "scholarshipName": "University of Auckland Doctoral Scholarship",
  "scholarshipAmount": "34568",
  "scholarshipType": "Amount",
  "scholarshipMetaData": [
    {
      "description": "Supports excellent domestic and international doctoral candidates whose research aligns with the strategic objectives of the University of Auckland."
    },
    {
      "description": "Applicable programmes: PhD, DMedSc, DClinPsy, DocFA, EdD and DHSc."
    },
    {
      "description": "Term: up to 42 months of full-time equivalent enrolment."
    },
    {
      "description": "Application: no separate application is required. Applicants indicate in their doctoral application that they wish to be considered."
    },
    {
      "description": "Selection: based on alignment with the strategic objectives of the University and the relevant faculty or research institute."
    },
    {
      "description": "Eligibility: applicant must be a domestic student, or an international student who is eligible to pay domestic fees for the doctoral programme."
    },
    {
      "description": "Eligibility: applicant must not already hold a doctorate or have previously received payment for a University of Auckland Doctoral Scholarship."
    },
    {
      "description": "Eligibility: applicant must not be enrolled in a doctoral programme, except for approved transfers."
    }
  ]
}
